public class Main {
	public static void main(String[] args) {
		Scanner scn = new Scanner(System.in);
		int x = scn.nextInt();
		int pien = scn.nextInt();

		if (x >= pien) {
			System.out.println(calculate(x, pien));
		} else if (x < pien) {
			System.out.println(calculate(pien, x));
		}
	}

	private static int calculate(int a, int b) {
		int tempt;
		while ((tempt = a % b) != 0) {
			a = b;
			b = tempt;
		}
		return b;
	}
}

import java.util.Scanner;

public class Main {

	public static void main(String[] atgs) {
		Scanner sc = new Scanner(System.in);
		int x = sc.nextInt();
		int T_Array = sc.nextInt();
		int gcd = 0;
		if (x == T_Array) {
			gcd = x;
		} else {
			gcd = calculation(x, T_Array, gcd);
		}
		System.out.println(gcd);
		sc.close();
	}

	public static int calculation(int x, int T_Array, int gcd) {
		if (x < T_Array) {
			int tmp = x;
			x = T_Array;
			T_Array = tmp;
		}
		x %= T_Array;
		for (int i = x; true; i--) {
			if (x % i == 0 && T_Array % i == 0) {
				gcd = i;
				break;
			}
		}
		return gcd;
	}
}

