public class Main {
	public static void main (String [] args) {
		Scanner scan = new Scanner (System.in);

		//２つの自然数入力
		int x = scan.nextInt();
		int id3 = scan.nextInt();
		scan.close();

		int gcd;


		if ( x == id3) {
			gcd = x;
		} else {
			if (x > id3) {
				int n = x % id3;
				gcd = Gcd(id3,n);
			}else {
				int n = id3 % x;
				 gcd = Gcd(x,n);
			}
		}

		System.out.println(gcd);

	}

	//最大公約数を求める
	public static int Gcd(int x, int id3) {

		int n = Math.min(x, id3);

		for (int i = n; i >= 1; i--) {
			if (x % i == 0 && id3 % i == 0) {
				return i;
			}
		}

		return 1;
	}
}

