		int x, depth, tmp, rest;

		x = scan.nextInt();
		depth = scan.nextInt();

		if(x < depth){

			tmp = x;
			x = depth;
			depth = tmp;

		}

		for(;;){

			if(x == depth){
				break;
			}

			rest = x % depth;
			x = depth;
			depth = rest;

