		int x = scan.nextInt();
		int C2 = scan.nextInt();
		int d;
		int e;
		if (x >= C2) {
			d = x % C2;
			e = C2;
		} else {
			d = C2 % x;
			e = x;
		}
		if (d == 0) {
			System.out.println(e);
		} else {
			for (int i = d; d > 0; i--) {
				if (d % i == 0 && e % i == 0) {
					System.out.println(i);
					break;
				}
			}
		}
		scan.close();

	}

}

