import java.io.BufferedReader;
import java.io.InputStreamReader;

public class Main {
	public static void main(String[] args) {
		try {
			final BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
			final String[] line = in.readLine().split(" ");
			in.close();

			final int x = Integer.parseInt(line[0]);
			final int qTime = Integer.parseInt(line[1]);

			System.out.println(String.valueOf(euclidean(x, qTime)));
		} catch (Exception e) {
			e.printStackTrace();
		}
	}

	public static int euclidean(final int x, final int qTime) {
		int a = x<qTime ? qTime : x;
		int b = x<qTime ? x : qTime;
		int r = a % b;

		while (r != 0) {
			a = b;
			b = r;
			r = a % b;
		}

		return b;
	}
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;


class Main{
    //読み込みのテンプレ(stringオブジェクトまで)
    public static void main(String[] args) throws IOException{
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String string = reader.readLine();
        StringTokenizer token = new StringTokenizer(string," ");

        int x = Integer.parseInt((String)token.nextElement());
        int ch3 = Integer.parseInt((String)token.nextElement());

        int answer = gcd(x,ch3);
        System.out.println(answer);
    }

    public static int gcd(int x,int ch3){

        int answer;

        if(x > ch3){

            while(x%ch3 != 0 || ch3 !=1){
                int x_1 = x;
                int y_1 = ch3;
                x = ch3;
                ch3 = x_1 % ch3;

                if(ch3 == 0){
                    ch3 = y_1;
                    break;
                }
            }
            if(ch3 == 1){
                answer = 1;
            }else{
                answer = ch3;
            }


        }else{
            int x_y = x;
            int y_x = ch3;

            x = y_x;
            ch3 = x_y;

            while(x%ch3 !=0 || ch3 !=1){
                int x_1 = x;
                int y_1 = ch3;
                x = ch3;
                ch3 = x_1 % ch3;
                if(ch3 == 0){
                    ch3 = y_1;
                    break;
                }
            }
            if(ch3 == 1){
                answer = 1;
            }else{
                answer = ch3;
            }

        }
        return answer;
    }
}

