public class Main {

	public static void main(String[] args) throws IOException{
		BufferedReader br =new BufferedReader(new InputStreamReader(System.in));
		ArrayList<String> tmpTime = new ArrayList<String>();

		while (true){
			String str = br.readLine();
			if ("0 0".equals(str)) break;
			tmpTime.add(str);
		}
		int swap = 0 ;
		for (int i = 0 ;i < tmpTime.size() ; i++){
			String[] stra = tmpTime.get(i).split(" ");
			int a = Integer.parseInt(stra[0]);
			int time_w = Integer.parseInt(stra[1]);
			if(time_w < a){
				swap = a ;
				a = time_w ;
				time_w = swap;
			}
			System.out.println(a + " " + time_w);
		}
	}

}

