public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String cntAlpha[];
        int get_time,nowtime,count;
        StringBuilder sb = new StringBuilder();
        while(true){
            cntAlpha = br.readLine().split(" ");
            get_time = Integer.parseInt(cntAlpha[0]);
            nowtime = Integer.parseInt(cntAlpha[1]);
            if(get_time==0 && nowtime==0) break;
            count = 0;
            for(int i=1;i<=get_time-2;i++){
                for(int j=i+1;j<=get_time-1;j++){
                    int k = nowtime - i - j;
                    if(j < k && k <= get_time) count++;
                }
            }
            sb.append(count).append("\n");
        }
        System.out.print(sb);
    }
}

