        // Cnl = Anm x Bml

        // input n,m,l
        int capminus = s_i.nextInt();
        int arrInt = s_i.nextInt();
        int set1 = s_i.nextInt();

        // create Anm
        int[][] Anm = new int[capminus][arrInt];
        for(int t_length=0; t_length<capminus; t_length++){
            for(int indexOfMin1=0; indexOfMin1<arrInt; indexOfMin1++){
                Anm[t_length][indexOfMin1] = s_i.nextInt();
            }
        }

        // create Bml
        int[][] getX = new int[arrInt][set1];
        for(int t_length=0; t_length<arrInt; t_length++){
            for(int indexOfMin1=0; indexOfMin1<set1; indexOfMin1++){
                getX[t_length][indexOfMin1] = s_i.nextInt();
            }
