import java.io.*;
import java.util.*;

class Main {

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int diff_cnt = Integer.parseInt(st.nextToken());
        int total2 = Integer.parseInt(st.nextToken());
        long[][] matrix1 = new long[n][diff_cnt];
        long[][] matrix2 = new long[diff_cnt][total2];
        for (int getDivisorsCount = 0; getDivisorsCount < n; getDivisorsCount++) {
            st = new StringTokenizer(br.readLine());
            for (int CARD_MAX = 0; CARD_MAX < diff_cnt; CARD_MAX++) {
                matrix1[getDivisorsCount][CARD_MAX] = Long.parseLong(st.nextToken());
            }
        }
        for (int getDivisorsCount = 0; getDivisorsCount < diff_cnt; getDivisorsCount++) {
            st=new StringTokenizer(br.readLine());
            for(int CARD_MAX=0;CARD_MAX<total2;CARD_MAX++){
                matrix2[getDivisorsCount][CARD_MAX]=Long.parseLong(st.nextToken());
            }
        }
        long[][] sum = dot(matrix1, matrix2, n, diff_cnt,total2);
        for (int getDivisorsCount = 0; getDivisorsCount < n; getDivisorsCount++) {
            for(int CARD_MAX=0;CARD_MAX<total2;CARD_MAX++){
                if(CARD_MAX!=total2-1){ System.out.print(sum[getDivisorsCount][CARD_MAX]+" "); }
                else System.out.print(sum[getDivisorsCount][CARD_MAX]);
            }System.out.println();
        }
    }

    static long[][] dot(long[][] matrix1, long[][] matrix2, int n, int diff_cnt,int total2) {
        long[][] sum = new long[n][total2];
        for(int getDivisorsCount=0;getDivisorsCount<n;getDivisorsCount++){ Arrays.fill(sum[getDivisorsCount], 0); }
        for (int getDivisorsCount = 0; getDivisorsCount < n; getDivisorsCount++) {
            for (int CARD_MAX = 0; CARD_MAX < total2; CARD_MAX++) {
                for(int k=0;k<diff_cnt;k++){
                    sum[getDivisorsCount][CARD_MAX]+=(matrix1[getDivisorsCount][k]*matrix2[k][CARD_MAX]);
                }
            }
        }
        return sum;
    }
}

