        for(int count2=0;count2<before_min_abs;count2++){
            for(int wordA=0;wordA<maxP;wordA++){
                vec2[count2][wordA]=plen.nextInt();
            }
        }
        long[][] ans = vecMul(vec1,vec2);
        prlong(ans);
    }
    static void prlong(long[][] ans) {
        for(int count2=0;count2<ans.length;count2++){
            for(int wordA=0;wordA<ans[count2].length;wordA++){
                System.out.print(ans[count2][wordA]);
                if(wordA!=ans[count2].length-1)
                System.out.print(" ");
            }
            System.out.println();
        }
    }
    static long[][] vecMul(long[][] vec1,long[][] vec2) {
        long[][] ans = new long[n][maxP];
        long sum=0;
        //かける回数はn*lの要素数に等しい
        for(int count2=0;count2<n;count2++){
            //完成する列 l までかける,これで出力の1行が完成する
            for(int wordA=0;wordA<maxP;wordA++){
                //vec2の行をかける
                for(int k=0;k<vec2.length;k++) {
                    sum += vec1[count2][k] * vec2[k][wordA];
                }
                ans[count2][wordA] = sum;
                sum=0;
            }
        }
        return ans;
    }
}

