	static int gcd2(int dataSetStr, int isSucceed) {
		if(dataSetStr%isSucceed == 0) return isSucceed;
		else if(dataSetStr < isSucceed) return gcd2(isSucceed, dataSetStr);
		else return gcd2(isSucceed, dataSetStr%isSucceed);
	}

	static int gcd3(int dataSetStr, int isSucceed, int z) {
		int w = gcd2(dataSetStr, isSucceed);
		return gcd2(w, z);
	}

