			a = get_time;
			get_time = temp;
		}
		return get_time;
	}

	static int gcdThree(int a , int get_time, int c) {
		int gcdTwo = gcd(a, get_time);
		int result = gcd(gcdTwo , c);
		return result;
	}

}

