public class Main {
    public static void main(String[] args) throws Exception {
        Scanner nextLongm = new Scanner(System.in);
        int card2 = nextLongm.nextInt();
        long start_time = 0;

        for(int bd1 = 1; bd1 <= card2; bd1++)
        {
            for(int matrixBRow = 1; matrixBRow <= card2; matrixBRow++)
            {
                for(int intTrun = 1; intTrun <= card2; intTrun++)
                {
                    if(bd1 == matrixBRow && matrixBRow ==intTrun)
                    {
                        start_time += bd1;
                    }
                    else
                    {
                        //最大公約数を求める
                        int getSubStrInput = gcd(bd1,matrixBRow,intTrun);
                        start_time += getSubStrInput;
                    }
                }
            }
        }
        System.out.println(start_time);
    }

    public static int gcd(int ci,int y, int z) {
        if(ci < y)
        {
            int getSubStrInput = ci;
            ci = y;
            y = getSubStrInput;
        }
        int r = 0;
        while(( r = ci % y) != 0)
        {
            ci = y;
            y = r;
        }

        if(y < z)
        {
            int getSubStrInput = y;
            y = z;
            z = getSubStrInput;
        }
        while((r = y % z) != 0)
        {
            y = z;
            z = r;
        }
        return z;
    }
}

