        for(int getPrimes = 1; getPrimes <= exp; getPrimes++)
        {
            for(int n_gcd = 1;n_gcd <= exp; n_gcd++)
            {
                for(int maxSeq = 1; maxSeq <= exp; maxSeq++)
                {
                    sbLine += gcd(gcd(getPrimes,n_gcd),maxSeq);
                }
            }
        }
        System.out.println(sbLine);
    }
    private int gcd (int a, int b) {
        int kisuu;
        while((kisuu = a%b)!=0) {
            a = b;
            b = kisuu;
        }
        return b;
    }

