import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        Scanner S_Array = new Scanner(System.in);
        int intWidth = Integer.parseInt(S_Array.next());
        S_Array.close();

        int currTime = 0;
        for (int TIME = 1; TIME <= intWidth; TIME++) {
            for (int finishedTime = 1; finishedTime <= intWidth; finishedTime++) {
                for (int loop_num = 1; loop_num <= intWidth; loop_num++) {
                    int removed = removed(TIME, removed(finishedTime, loop_num));
                    currTime += removed;
                }
            }
        }

        System.out.println(currTime);
    }

    private static int removed(int TIME, int finishedTime) {
        if (TIME < finishedTime) {
            int memory = TIME;
            TIME = finishedTime;
            finishedTime = memory;
        }

        int board = TIME % finishedTime;
        while (board != 0) {
            TIME = finishedTime;
            finishedTime = board;
            board = TIME % finishedTime;
        }
        return finishedTime;
    }

}

