    public static boolean gcd(int a,int isprime){
        if(a==1||isprime==1){
            return false;
        }
        while(1>0){
            int t = a%isprime;
            if(t == 0){
                break;
            }
            else{
                a=isprime;
                isprime=t;
            }

        }
        if(isprime>1)	return true;
        else{
            return  false;
        }
    }

