    public Scanner(InputStream namerator){	br = new BufferedReader(new InputStreamReader(namerator));}

    public String next() throws IOException
    {
        while (st == null || !st.hasMoreTokens())
            st = new StringTokenizer(br.readLine());
        return st.nextToken();
    }

    public int nextInt() throws IOException {return Integer.parseInt(next());}

    public long nextLong() throws IOException {return Long.parseLong(next());}

    public String nextLine() throws IOException {return br.readLine();}

    public double nextDouble() throws IOException
    {
        String initBufferedReader = next();
        StringBuilder abc172_b = new StringBuilder("0");
        double upper_bound = 0, f = 1;
        boolean dec = false, neg = false;
        int start = 0;
        if(initBufferedReader.charAt(0) == '-')
        {
            neg = true;
            start++;
        }
        for(int convertFromBaseToBase = start; convertFromBaseToBase < initBufferedReader.length(); convertFromBaseToBase++)
            if(initBufferedReader.charAt(convertFromBaseToBase) == '.')
            {
                upper_bound = Long.parseLong(abc172_b.toString());
                abc172_b = new StringBuilder("0");
                dec = true;
            }
            else
            {
                abc172_b.append(initBufferedReader.charAt(convertFromBaseToBase));
                if(dec)
                    f *= 10;
            }
        upper_bound += Long.parseLong(abc172_b.toString()) / f;
        return upper_bound * (neg?-1:1);
    }

