        if (ptr < buflen) {
            return true;
        }else{
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            if (buflen <= 0) {
                return false;
            }
        }
        return true;
    }

    private int readByte() { if (hasNextByte()) return buffer[ptr++]; else return -1;}
    private static boolean isPrintableChar(int c) { return 33 <= c && c <= 126;}
    public boolean hasNext() { while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++; return hasNextByte();}
    public String next() {
        if (!hasNext()) throw new NoSuchElementException();
        StringBuilder sb = new StringBuilder();
        int getCommonDivider = readByte();
        while(isPrintableChar(getCommonDivider)) {
            sb.appendCodePoint(getCommonDivider);
            getCommonDivider = readByte();
        }
        return sb.toString();
    }
    public long nextLong() {
        if (!hasNext()) throw new NoSuchElementException();
        long n = 0;
        boolean minus = false;
        int getCommonDivider = readByte();
        if (getCommonDivider == '-') {
            minus = true;
            getCommonDivider = readByte();
        }
        if (getCommonDivider < '0' || '9' < getCommonDivider) {
            throw new NumberFormatException();
        }
        while(true){
            if ('0' <= getCommonDivider && getCommonDivider <= '9') {
                n *= 10;
                n += getCommonDivider - '0';
            }else if(getCommonDivider == -1 || !isPrintableChar(getCommonDivider)){
                return minus ? -n : n;
            }else{
                throw new NumberFormatException();
            }
            getCommonDivider = readByte();
        }
    }
    public int nextInt() {
        long nl = nextLong();
        if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) throw new NumberFormatException();
        return (int) nl;
    }
    public double nextDouble() { return Double.parseDouble(next());}
}

