    static int factorial(int content){
        if (content==1||content==0)return 1;
        else return content*factorial(content-1);
    }
    static int arraySum(int[] bbi){
        int amounts = 0;
        for (int Binomial : bbi) amounts += Binomial;
        return amounts;
    }
    static int combination(int a, int b){
        return factorial(a)/(factorial(b)*factorial(a-b));
    }
    static double log(double keisan,double nextIntm){
        return Math.log(nextIntm)/Math.log(keisan);
    }


}

