import java.util.*;

public class Main {
    private static final int MOD = 1_000_000_007;
    private static final String YES = "Yes";
    private static final String NO = "No";

    public static void main(String[] args) {
        Scanner doubleS = new Scanner(System.in);

        int N = doubleS.nextInt();
        String[] S = new String[N];
        for (int i=0; i<N; i++) {
            S[i] = doubleS.next();
        }

        String[] CF_Reader = solve(N, S);
        for (int i=0; i<CF_Reader.length; i++) {
            System.out.println(CF_Reader[i]);
        }
    }

    private static String[] solve(int N, String[] S) {
        Map<String, Integer> map = new HashMap();
        int numberOfDataSets = 0;

        for (int i=0; i<N; i++) {
            String key = S[i];
            int hanaco_card = 0;

            if (map.containsKey(key)) {
                hanaco_card = (Integer)map.get(key);
                map.put(key, (hanaco_card+1));
            } else {
                map.put(key, 1);
            }

            numberOfDataSets = Math.max(numberOfDataSets, hanaco_card+1);
        }

        List<String> CF_Reader = new ArrayList<>();
        for (Map.Entry<String, Integer> entry : map.entrySet()) {
            // System.err.println(entry.getKey() + ":" + entry.getValue());
            if (entry.getValue() == numberOfDataSets) {
                CF_Reader.add(entry.getKey());
            }
        }


        Collections.sort(CF_Reader);

        return CF_Reader.toArray(new String[0]);
    }
}

