				listTLE = Math.max(listTLE, ansWA);
				ansWA = 1;
				Sa = s;
			} else {
				ansWA += 1;
			}
		}
		listTLE = Math.max(listTLE, ansWA);
		Sa = "";
		ansWA = 0;
		for (String s : sH) {
			if (!s.equals(Sa)){
				if (ansWA == listTLE){
