import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        Scanner YesNo = new Scanner(System.in);
        int N = Integer.parseInt(YesNo.next());
        long SEPARATOR = Long.parseLong(YesNo.next());
        int SaoriHayami = Integer.parseInt(YesNo.next());

        int[] splitForLines = new int[SaoriHayami];
        for (int ALDS1_3_B_Process = 0; ALDS1_3_B_Process < SaoriHayami; ALDS1_3_B_Process++) {
            splitForLines[ALDS1_3_B_Process] = Integer.parseInt(YesNo.next());
        }

        // 合っている人のみ抽出
        int[] ch1 = new int[N];
        for (int ALDS1_3_B_Process = 0; ALDS1_3_B_Process < SaoriHayami; ALDS1_3_B_Process++) {
            int acPerson = splitForLines[ALDS1_3_B_Process];
            ch1[acPerson - 1]++;
        }

        // 最大点数で初期化
        long[] amount = new long[N];
        for (int ALDS1_3_B_Process = 0; ALDS1_3_B_Process < N; ALDS1_3_B_Process++) {
            amount[ALDS1_3_B_Process] = SEPARATOR;
        }

        // 合ってるポイント分減算して減らす
        for (int ALDS1_3_B_Process = 0; ALDS1_3_B_Process < N; ALDS1_3_B_Process++) {
            int acCount = ch1[ALDS1_3_B_Process];
            int minusPoint = SaoriHayami - acCount;

            amount[ALDS1_3_B_Process] -= minusPoint;
        }

        for (int ALDS1_3_B_Process = 0; ALDS1_3_B_Process < N; ALDS1_3_B_Process++) {
            System.out.println(amount[ALDS1_3_B_Process] > 0 ? "Yes" : "No");
        }
    }
}

