import java.io.PrintWriter;
import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = Integer.parseInt(sc.next());
        long crane_num = Long.parseLong(sc.next());
        int arraySizeS = Integer.parseInt(sc.next());

        int[] A = new int[arraySizeS];
        for (int i = 0; i < arraySizeS; i++) {
            A[i] = Integer.parseInt(sc.next());
        }

        solve(N, arraySizeS, crane_num, A);
    }

    public static void solve(int n, int N_str, long END, int[] a) {
        long[] dp = new long[n];
        for (int i = 0; i < N_str; i++) {
            int winner = a[i];
            dp[winner - 1] = dp[winner - 1] + 1;
        }

        PrintWriter out = new PrintWriter(System.out);
        for (long prime_10000 : dp) {
            if (N_str - END >= prime_10000)
                out.println("No");
            else
                out.println("Yes");
        }
        out.flush();
    }
}

