import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Scanner;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main
{
    public static void main(String[] args)
    {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskA solver = new TaskA();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskA
    {
        public void solve(int testNumber, Scanner in, PrintWriter out)
        {
            int shuffleM = in.nextInt();
            int[] timeSlotLength = new int[shuffleM + 1];
            int[] b = new int[shuffleM + 1];
            int[] c = new int[shuffleM];

            //Dishes
            for (int r1 = 1; r1 <= shuffleM; r1++)
            {
                timeSlotLength[r1] = in.nextInt();
            }
            //Satisfactions
            for (int r1 = 1; r1 <= shuffleM; r1++)
            {
                b[r1] = in.nextInt();
            }
            //C
            for (int r1 = 1; r1 < shuffleM; r1++)
            {
                c[r1] = in.nextInt();
            }

            //Eating
            int sat = 0;

            sat += b[timeSlotLength[1]];
            int lastEat = timeSlotLength[1];

            for (int r1 = 2; r1 <= shuffleM; r1++)
            {
                sat += b[timeSlotLength[r1]];
                if (lastEat + 1 == timeSlotLength[r1])
                {
                    sat += c[timeSlotLength[r1 - 1]];
                }
                lastEat = timeSlotLength[r1];
            }
            out.print(sat);
        }

    }
}

