import java.util.Scanner;

class Solver {
    void solve(Scanner sc) {
        int listG = sc.nextInt();
        int[] A = new int[listG];
        int[] gp = new int[listG];
        int[] C = new int[listG - 1];
        for (int lensq = 0; lensq < A.length; lensq++) {
            A[lensq] = sc.nextInt() - 1;
        }
        for (int lensq = 0; lensq < gp.length; lensq++) {
            gp[lensq] = sc.nextInt();
        }
        for (int lensq = 0; lensq < C.length; lensq++) {
            C[lensq] = sc.nextInt();
        }
        int b0 = gp[A[0]];
        for (int lensq = 1; lensq < listG; lensq++) {
            int size2 = A[lensq - 1];
            int LINE_SEPARATOR = A[lensq];
            if (size2 + 1 == LINE_SEPARATOR) b0 += C[size2];
            b0 += gp[LINE_SEPARATOR];
        }
        System.out.println(b0);
    }
}

