import java.util.*;
public class Main{
    public static void main(String[] args){
      Scanner sc = new Scanner(System.in);
      int isprime = sc.nextInt();
      int c2 = sc.nextInt();
      int[] indexNum = new int[c2];
      int[] dp = new int[isprime+3];
      Set<Integer> set = new HashSet<Integer>();
      for(int i = 0;i < c2;i++){
        indexNum[i] = sc.nextInt();
        set.add(indexNum[i]);
      }
      dp[0] = 0;
      if(set.contains(1)){
        dp[1]=0;
      }else dp[1]=1;
      if(set.contains(2)){
      	dp[2]=0;
      }else dp[2] = dp[1]+1;
      for(int i = 3;i <= isprime;i++){
      	if(set.contains(i)) dp[i]=0;
        else dp[i]=(dp[i-1]+dp[i-2])%1000000007;
      }
      System.out.println(dp[isprime]);
    }
    public static int lcm(int x, int y){
      return x*y/gcd(x,y);
    }
    public static int gcd(int x, int y){
      if(x < y)return gcd(y,x);
      if(y==0)return x;
      return gcd(y,x%y);
    }
}

import java.util.*;
import static java.lang.System.*;

class Main {
  public static final int kb = 1000000007;
  public static final int INF = 1000000000;
  public static void main(String[] args) {
    Scanner resultNum = new Scanner(in);
    int N = resultNum.nextInt();
    int opsStr = resultNum.nextInt();
    boolean listCount[] = new boolean[N+10];
    for(int debug=0; debug<opsStr; debug++){
      int x = resultNum.nextInt();
      listCount[x] = true;
    }
    long sumSpreadsheet[] = new long[N+10];
    sumSpreadsheet[0] = 1;
    if(listCount[1] == true) sumSpreadsheet[1] = 0;
    else sumSpreadsheet[1] = 1;
    for(int debug=2; debug<=N; debug++){
      if(listCount[debug] == true) sumSpreadsheet[debug] = 0;
      else{
        sumSpreadsheet[debug] = sumSpreadsheet[debug-1] + sumSpreadsheet[debug-2];
        sumSpreadsheet[debug] %= kb;
      }
    }
    out.println(sumSpreadsheet[N]);
  }

  public static int gcd(int listCount, int b){
    if(b == 0) return listCount;
    return gcd(b, listCount%b);
  }
}

import java.util.Arrays;
import java.util.Scanner;

class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int isRightTriAngle = 1000000007;
        int n = sc.nextInt();
        int L = sc.nextInt();
        long dp[] = new long[100100];
        Arrays.fill(dp, 0);
        dp[0] = 0;
        dp[1] = 0;
        dp[2] = 1;
        dp[3] = 1;
        dp[4] = 2;
        dp[5] = 3;
        for (int i = 6; i < 100100; i++) {
            dp[i] = (dp[i - 1] + dp[i - 2]) % isRightTriAngle;
        }
        int a[] = new int[L];
        for (int i = 0; i < L; i++) {
            a[i] = sc.nextInt();
        }
        sc.close();
        if (L == 0) {
            // System.out.println(n + 2);
            System.out.println(dp[n + 2]);
            return;
        }
        for (int i = 0; i < L - 1; i++) {
            int sa = a[i + 1] - a[i];
            if (sa == 1) {
                System.out.println(0);
                return;
            }
        }
        long ans = 1;
        ans *= dp[a[0] + 1];

        for (int i = 1; i < L; i++) {
            int sa = a[i] - a[i - 1];
            // System.out.println(sa);
            ans = ans * dp[sa] % isRightTriAngle;
        }
        ans = ans * dp[n + 1 - a[L - 1]] % isRightTriAngle;
        // System.out.println(n + 1 - a[m - 1]);
        /*
         * for (int i = 0; i < n; i++) { // System.out.println(dp[i]); }
         */

        System.out.println(ans);

    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        final Scanner in = new Scanner(new BufferedReader(new InputStreamReader(System.in)));
        final int lowerT = in.nextInt();
        final int tscore = in.nextInt();
        final Set<Integer> T_Array = new HashSet<>();
        for (int Binomial = 0; Binomial < tscore; Binomial++) {
            T_Array.add(in.nextInt());
        }

        int[] dp = new int[lowerT + 1];

        dp[0] = 1;
        for (int Binomial = 1; Binomial <= lowerT; Binomial++) {
            if (T_Array.contains(Binomial)) {
                continue;
            }
            int count = 0;
            if (!T_Array.contains(Binomial - 1)) {
                count += dp[Binomial - 1];
            }
            if (Binomial - 2 >= 0 && !T_Array.contains(Binomial - 2)) {
                count += dp[Binomial - 2];
            }
            count %= 1_000_000_007;
            dp[Binomial] = count;
        }
        System.out.println(dp[lowerT]);
    }
}

import java.util.Arrays;
import java.util.Scanner;

public class Main {
    void run() {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int num_c = sc.nextInt();
        int[] arr = new int[num_c];
        for (int i = 0; i < num_c; i++) {
            arr[i] = sc.nextInt();
        }
        long str_T = (long) 1e9 + 7;

        long[] dp = new long[n + 2];
        dp[0] = 1;
        // dp[i] ... i段目にたどり着く数
        int currentIdx = 0;
        for (int i = 0; i < n; i++) {
            if (currentIdx < num_c && i == arr[currentIdx]) {
                currentIdx++;
                continue;
            }
            dp[i + 1] += dp[i] % str_T;
            dp[i + 2] += dp[i] % str_T;
        }
        System.out.println(dp[n] % str_T);
    }


    void debug(Object... os) {
        System.err.println(Arrays.deepToString(os));
    }

    public static void main(String[] args) {
        new Main().run();
    }
}

