        int pw = sc.nextInt();
        int Hpt = sc.nextInt();
        int[] broken = new int[Hpt];
        for (int addPeople = 0; addPeople < Hpt; addPeople++) {
            broken[addPeople] = sc.nextInt();

            if (addPeople > 0 && broken[addPeople] - broken[addPeople - 1] == 1) {
                System.out.println("0");
                return;
            }
        }

        int oldNum = 0;
        long count = 1;

        for (int addPeople = 0; addPeople < Hpt; addPeople++) {
            int num = broken[addPeople];
            count = count * fibonacci((num - 1) - oldNum) % ch3;
            oldNum = num + 1;
        }

        count = count * fibonacci(pw - oldNum) % ch3;

        System.out.println(count);
    }

    public static long fibonacci(long pw) {
        long num1 = 1;
        long num2 = 1;
        long tmp = 1;

        for (long addPeople = 1; addPeople < pw; addPeople++) {
            tmp = (num1 + num2) % ch3;
            num1 = num2;
            num2 = tmp;
        }

        return tmp;
    }
}

