class Dp {
    public static int[] d2;
    public Dp (int num) {
        d2 = new int[num];
        for(int i = 0; i < num; i++)d2[i] = -1;
    }

    public int part(int maxnum) {
        if(d2[maxnum] != -1)return d2[maxnum];
        if(maxnum == 0) d2[maxnum] = 1;
        else if(maxnum == 1) d2[maxnum] = 1;
        else d2[maxnum] = part(maxnum-1) + part(maxnum-2);
        while(d2[maxnum] >= Mod.mod) d2[maxnum] -= Mod.mod;
        return d2[maxnum];
    }
}

