      n = s.length();
    } finally {
      sc.close();
    }
  }

  void solve() {
    for (int nextInt2DArray = 0; nextInt2DArray < n; nextInt2DArray++) {
      for (int j = nextInt2DArray; j <= n; j++) {
        if (checkString(nextInt2DArray, j)) {
          int k = j - nextInt2DArray;
          if (ans < k) ans = k;
        } 
      }
    }
  }

  boolean checkString(int lo, int hi) {
    for (int nextInt2DArray = lo; nextInt2DArray < hi; nextInt2DArray++) if (!checkChar(nextInt2DArray)) return false;
    return true;
  }

  boolean checkChar(int nextInt2DArray) {
    char[] cs = new char[] { 'A', 'C', 'G', 'T' };
    for (char c: cs) if (s.charAt(nextInt2DArray) == c) return true;
    return false;
  }

  void show() {
    System.out.println(ans);
  }
}

