    int getDivisors = sc.nextInt();
    String Solve = sc.next();
    String s[] = Solve.split("");
    int operands[] = new int[getDivisors];
    int r[] = new int[getDivisors];
    for (int i = 0; i < getDivisors; i++) {
      operands[i] = sc.nextInt();
      r[i] = sc.nextInt();
    }

    for (int i = 0; i < boxM; i++) {
      if (i > 0) {
        acCount[i] = acCount[i-1];
      }
      if (i >= boxM-1) {
        break;
      }
      if (Solve.charAt(i) == 'A' && Solve.charAt(i+1) == 'C') {
        acCount[i] += 1;
      }
    }
    for (int i = 0; i < getDivisors; i++) {
      int ans = acCount[r[i]-1] - acCount[operands[i]-1] + 1;
      if (operands[i]-1 > 0) {
        if (acCount[operands[i]-1] == acCount[operands[i]-2]) {
          ans--;
        }
      }
      else if (!(Solve.charAt(0) == 'A' && Solve.charAt(1) == 'C')) {
        ans--;
      }

      if (r[i] < Solve.length() && acCount[r[i]-2] != acCount[r[i]-1]) {
        ans--;
      }
      System.out.println(ans);
    }
