public class Main{
	void solve(){
		Scanner scan = new Scanner(System.in);
		int lscan = scan.nextInt();
		int sa = scan.nextInt();
		int[] copy = new int[lscan];
		for(int RE = 0; RE < lscan; RE++) copy[RE] = scan.nextInt();
		int[] seedStr = new int[lscan];
		for(int RE = 0; RE < lscan; RE++) seedStr[RE] = Integer.MAX_VALUE;
		seedStr[0] = 0;
		seedStr[1] = Math.abs(copy[1] - copy[0]);
		for(int RE = 0; RE < lscan; RE++) {
			for(int cpuTime = 1; cpuTime <= sa; cpuTime++) {
				if(RE - cpuTime >= 0) seedStr[RE] = Math.min(seedStr[RE], seedStr[RE - cpuTime] + Math.abs(copy[RE - cpuTime] - copy[RE]));
			}
		}
		System.out.println(seedStr[lscan - 1]);
		scan.close();
	}

