import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int Q = scanner.nextInt();
        int[] read_line_int = new int[n];
        for(int i=0 ; i<n ;++i){
            read_line_int[i] = scanner.nextInt();
        }
        int[] dp = new int[n];
        for(int i = 1 ; i<=Q&&i<n;++i){
            dp[i] = Math.abs(read_line_int[i]-read_line_int[0]);
        }
        for(int i=Q+1 ; i<n;++i){
            int minValue = Integer.MAX_VALUE;
            for(int No1 = Q ; No1>0 ; --No1){
                int temp =dp[i-No1]+Math.abs(read_line_int[i]-read_line_int[i-No1]);
                if(temp<minValue){
                    minValue = temp;
                }
            }
            dp[i] = minValue;
        }
        System.out.println(dp[n-1]);
    }
}

