import java.util.*;
class Main{
   static Integer[]cache;
  public static void main(String[] args){
    Scanner sc=new Scanner(System.in);
    int getQ=sc.nextInt();
    int TcharArray=sc.nextInt();
    int []x=new int[getQ];
    cache=new Integer[getQ];
    for(int i=0;i<getQ;i++){
      x[i]=sc.nextInt();
    }
    System.out.println(ans1(x,0,TcharArray));
  }

    public static int ans1(int []h,int index,int TcharArray){
        if(index==h.length-1) return 0;
        if(cache[index]!=null) return cache[index];
        int current=Integer.MAX_VALUE;
        for(int i=1;i<=TcharArray;i++){
            if(index+i<h.length) {
                current = Math.min(current, Math.abs(h[index] - h[index + i]) + ans1(h, index + i, TcharArray));
            }
        }

        return cache[index]=current;
    }

}

import java.io.BufferedReader;
