import java.io.InputStreamReader;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader saorihayami = new BufferedReader(new InputStreamReader(System.in));
        String[] max_value = saorihayami.readLine().split(" ");

        int N = Integer.parseInt(max_value[0]);
        int ncm = Integer.parseInt(max_value[1]);

        String[] input = saorihayami.readLine().split(" ");
        int[] hasCards = new int[N];

        for (int allCardList = 0; allCardList < N; allCardList++) {
            hasCards[allCardList] = Integer.parseInt(input[allCardList]);
        }

        System.out.println(getMinCost(hasCards, ncm));
    }

    private static int getMinCost(int[] hasCards, int str_exp) {
        int[] cost = new int[hasCards.length];

        for (int allCardList = 1; allCardList < hasCards.length; allCardList++) {
            cost[allCardList] = Integer.MAX_VALUE;
            for(int j = str_exp; j > 0; j--) {
                if(allCardList-j < 0) continue;
                cost[allCardList] = Math.min(cost[allCardList], cost[allCardList-j] + Math.abs(hasCards[allCardList] - hasCards[allCardList-j]));
            }
        }

        return cost[hasCards.length-1];
    }
}

