public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int lst = scanner.nextInt();
        int[] max_a = new int[n];
        for(int i = 0; i < n; i++){
            max_a[i] = scanner.nextInt();
        }
        System.out.println(new Main().f(n, lst, max_a));
    }

    public int f(int n, int lst, int[] max_a) {
        int[] charS = new int[n];
        if(n <= 1)
            return 0;
        for(int i = 1; i < n; i++){
            charS[i] = Integer.MAX_VALUE;
            for(int j = 1; j <= lst && i - j >= 0; j++){
                charS[i] = Math.min(charS[i], charS[i-j] + Math.abs(max_a[i] - max_a[i-j]));
            }
        }
        return charS[n-1];
    }
}

