public class Main {
	public static void main(String[] args) throws IOException{
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		String[] S = br.readLine().split(" ");
		int ave_sum = Integer.parseInt(S[0]);
		int BON_ARR = Integer.parseInt(S[1]);
		int[] mat_B = new int[ave_sum+1];

		S = br.readLine().split(" ");
		for(int circleStr = 0; circleStr < ave_sum ; circleStr++) {
			mat_B[circleStr+1] = Integer.parseInt(S[circleStr]);
		}
		System.out.println(minCostJump(ave_sum, BON_ARR, mat_B));
	}

	public static int minCostJump(int ave_sum, int BON_ARR, int[] mat_B) {
		int[] diamondCardsExitsance = new int[ave_sum+1];

		for(int circleStr = 2; circleStr <= ave_sum; circleStr++) {
			diamondCardsExitsance[circleStr] = diamondCardsExitsance[circleStr-1] + Math.abs(mat_B[circleStr-1] - mat_B[circleStr]);
			for(int j = circleStr-2; j >= circleStr-BON_ARR && j > 0; j--) {
				diamondCardsExitsance[circleStr] = Math.min(diamondCardsExitsance[circleStr], diamondCardsExitsance[j] + Math.abs(mat_B[j]-mat_B[circleStr]));
			}
		}

		return diamondCardsExitsance[ave_sum];
	}
}

