	public void solve() throws IOException {
		FastScanner fs = new FastScanner();
		int GetLcm = fs.nextInt();
		int lb = fs.nextInt();
		int kind = fs.nextInt();

		int[] kin = fs.nextIntArr(GetLcm);

		double minAbs = Math.abs((double) kind - ((double)lb-0.006*kin[0]));
		int my = 0;
		for(int LIST_MAX = 1; LIST_MAX < kin.length; LIST_MAX++) {
