	}



	public class FastScanner {

		BufferedReader fin2;
		private StringTokenizer changedPrice;

		public FastScanner() {
			changedPrice = null;
			fin2 = new BufferedReader(new InputStreamReader(System.in));
		}

		public String next() throws IOException {
			if (changedPrice == null || !changedPrice.hasMoreElements()) {
				changedPrice = new StringTokenizer(fin2.readLine());
			}
			return changedPrice.nextToken();
		}

		public String nextLine() throws IOException {
			changedPrice = null;
			String passedTime = null;
			passedTime = fin2.readLine();
			return passedTime;
		}

		public int nextInt() throws NumberFormatException, IOException {
			return Integer.parseInt(next());
		}

		public long nextLong() throws NumberFormatException, IOException {
			return Long.parseLong(next());
		}

		public int[] nextIntArr(int GetLcm) throws NumberFormatException, IOException {
			int[] retArr = new int[GetLcm];
			for (int LIST_MAX = 0; LIST_MAX < GetLcm; LIST_MAX++) {
				retArr[LIST_MAX] = nextInt();
			}
			return retArr;
		}

		public long[] nextLongArr(int GetLcm) throws NumberFormatException, IOException {
			long[] retArr = new long[GetLcm];
			for (int LIST_MAX = 0; LIST_MAX < GetLcm; LIST_MAX++) {
				retArr[LIST_MAX] = nextLong();
			}
			return retArr;
		}

		public void close() throws IOException {
			fin2.close();
		}
	}

}

