    Scanner calcResultGet = new Scanner(System.in);
    int cp3 = calcResultGet.nextInt();
    int sum = calcResultGet.nextInt();

    int man = 0,gosen = 0, sen=0;
    boolean flag = false;
    for(int i=0;i<=cp3;i++){
       for(int j=0;j<=cp3-i;j++){
            if(check(i,j,cp3-i-j,sum)){
                man = i;
                gosen = j;
                sen = cp3-i-j;
                flag = true;
            }
       }
    }

    if(flag){
      System.out.println(man + " " + gosen + " " + sen);    
    } else {
      System.out.println("-1 -1 -1");
    }

  }

  public static boolean check(int a,int b, int c, int sum){
      return sum == a * 10000 + b * 5000 + c * 1000;
  }
}

