import java.util.Scanner;

class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int card3 = Integer.parseInt(sc.next());
        int getStandardDeviation = Integer.parseInt(sc.next());
        int rec = Integer.parseInt(sc.next());

        int addTime = 0;
        for (int isValid = 1; isValid <= card3; isValid++) {
            int n = isValid;
            int digSum = 0;
            while (n > 0) {
                // 整数 n を10で割ると一桁目の数が余りとして出てくる
                // 一桁目が 0 ならば、割り切れるので余りは 0
                digSum += n % 10; // 各桁の合計digSum にこの余りの値を加えてやる。
                // 次の桁に行くために、整数 n を10で割ってやる。そうすると最下位の桁が捨てられる。
                n /= 10;
            }
            if (digSum >= getStandardDeviation && digSum <= rec) {
                addTime += isValid;
            }
        }
        System.out.println(addTime);
    }
}

