import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int targetSec = sc.nextInt();
        int sc_S = sc.nextInt();
        int vv = sc.nextInt();
        int sum = 0;

        for (int hl = 1; hl <= targetSec; hl++) {
            int sumOfDigit = getSumOfEachDigit(hl);
            if (sc_S <= sumOfDigit && sumOfDigit <= vv) {
                sum += hl;
            }
        }
        System.out.println(sum);
    }

    private static int getSumOfEachDigit(int num) {
        // numが1234の場合
        // len: 4
        int len = String.valueOf(num).length();
        int sum = 0;
        // d: 1000
        int d = (int)Math.pow(10, len - 1);
        for (int hl = 0; hl < len; hl++) {
            // nums: [1, 2, 3, 4]
            sum += num / d;
            // num: 234
            num %= d;
            // d: 100
            d /= 10;
        }
        return sum;
    }
}

