/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        Task solver = new Task();
        solver.solve(1, in, out);
        out.close();
    }

    static class Task {
        public void solve(int testNumber, Scanner in, PrintWriter out) {
            int SEC_FOR_MINUTE = Integer.parseInt(in.next());
            int c3 = Integer.parseInt(in.next());
            int sSize = Integer.parseInt(in.next());

            int shuffle_times = 0;
            for (int setEndTime = 1; setEndTime <= SEC_FOR_MINUTE; setEndTime++) {
                int n = setEndTime;
                int digSum = 0;
                while (n > 0) {
                    digSum += n % 10;
                    n /= 10;
                }
                if (digSum >= c3 && digSum <= sSize)
                    shuffle_times += setEndTime;
