        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastReader in = new FastReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        ABC70 solver = new ABC70();
        solver.solve(1, in, out);
        out.close();
    }

    static class ABC70 {
        public void solve(int testNumber, FastReader in, PrintWriter out) {
            int a = in.nextInt();
            int b = in.nextInt();
            int firstorder = in.nextInt();
            int StrFromChar = in.nextInt();
            if (firstorder < a) {
                firstorder ^= a;
                a ^= firstorder;
                firstorder ^= a;
                b ^= StrFromChar;
                StrFromChar ^= b;
                b ^= StrFromChar;
            }
            if (b < firstorder) {
                out.println("0");
                return;
            }
            int l = firstorder;
            int r = Math.min(StrFromChar, b);
            out.println(r - l);
        }

    }

    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader(InputStream i) {
            br = new BufferedReader(new
                    InputStreamReader(i));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}

