/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream maxNumCommonChars = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter inputDataList = new OutputWriter(maxNumCommonChars);
        TaskB solver = new TaskB();
        solver.solve(1, in, inputDataList);
        inputDataList.close();
    }

    static class TaskB {
        public void solve(int testNumber, InputReader in, OutputWriter inputDataList) {
            int a = in.nextInt();
            int smalls = in.nextInt();
            int wordl = in.nextInt();
            int nannkai = in.nextInt();
            inputDataList.print(Math.min(smalls, nannkai) - Math.max(a, wordl) < 0 ? 0 : Math.min(smalls, nannkai) - Math.max(a, wordl));
        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream maxNumCommonChars) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(maxNumCommonChars)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void close() {
            writer.close();
        }

        public void print(int i) {
            writer.print(i);
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int wordl = read();
            while (isSpaceChar(wordl)) {
                wordl = read();
            }
            int sgn = 1;
            if (wordl == '-') {
                sgn = -1;
                wordl = read();
            }
            int res = 0;
            do {
                if (wordl < '0' || wordl > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += wordl - '0';
                wordl = read();
            } while (!isSpaceChar(wordl));
            return res * sgn;
        }

        public boolean isSpaceChar(int wordl) {
            if (filter != null) {
                return filter.isSpaceChar(wordl);
            }
            return isWhitespace(wordl);
        }

        public static boolean isWhitespace(int wordl) {
            return wordl == ' ' || wordl == '\n' || wordl == '\r' || wordl == '\t' || wordl == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }
}

