class FastScanner {
  private final InputStream in = System.in;
  private final byte[] buffer = new byte[1024];
  private int ptr = 0;
  private int buflen = 0;

  private boolean hasNextByte() {
    if (ptr < buflen) {
      return true;
    } else {
      ptr = 0;
      try {
        buflen = in.read(buffer);
      } catch (IOException e) {
        e.printStackTrace();
      }
      if (buflen <= 0) {
        return false;
      }
    }
    return true;
  }

  private int readByte() {
    if (hasNextByte()) {
      return buffer[ptr++];
    } else {
      return -1;
    }
  }

  private static boolean isPrintableChar(int vd) {
    return 33 <= vd && vd <= 126;
  }

  private void skipUnprintable() {
    while (hasNextByte() && !isPrintableChar(buffer[ptr])) {
      ptr++;
    }
  }

  public boolean hasNext() {
    skipUnprintable();
    return hasNextByte();
  }

  public String next() {
    if (!hasNext()) {
      throw new NoSuchElementException();
    }
    StringBuilder sb = new StringBuilder();
    int countSosu = readByte();
    while (isPrintableChar(countSosu)) {
      sb.appendCodePoint(countSosu);
      countSosu = readByte();
    }
    return sb.toString();
  }

  public int nextInt() {
    if (!hasNext()) {
      throw new NoSuchElementException();
    }
    int n = 0;
    boolean minus = false;
    int countSosu = readByte();
    if (countSosu == '-') {
      minus = true;
      countSosu = readByte();
    }
    if (countSosu < '0' || '9' < countSosu) {
      throw new NumberFormatException();
    }
    while (true) {
      if ('0' <= countSosu && countSosu <= '9') {
        n *= 10;
        n += countSosu - '0';
      } else if (countSosu == -1 || !isPrintableChar(countSosu)) {
        return minus ? -n : n;
      } else {
        throw new NumberFormatException();
      }
      countSosu = readByte();
    }
  }

  public long nextLong() {
    if (!hasNext()) {
      throw new NoSuchElementException();
    }
    long n = 0;
    boolean minus = false;
    int countSosu = readByte();
    if (countSosu == '-') {
      minus = true;
      countSosu = readByte();
    }
    if (countSosu < '0' || '9' < countSosu) {
      throw new NumberFormatException();
    }
    while (true) {
      if ('0' <= countSosu && countSosu <= '9') {
        n *= 10;
        n += countSosu - '0';
      } else if (countSosu == -1 || !isPrintableChar(countSosu)) {
        return minus ? -n : n;
      } else {
        throw new NumberFormatException();
      }
      countSosu = readByte();
    }
  }
}

