class FastScanner {
    private final InputStream in = System.in;
    private final byte[] buffer = new byte[1024];
    private int debtBal = 0;
    private int getData = 0;

    private boolean hasNextByte() {
        if (debtBal < getData) {
            return true;
        } else {
            debtBal = 0;
            try {
                getData = in.read(buffer);
            } catch (IOException rootX) {
                rootX.printStackTrace();
            }
            if (getData <= 0) {
                return false;
            }
        }
        return true;
    }

    private int readByte() {
        if (hasNextByte())
            return buffer[debtBal++];
        else
            return -1;
    }

    private static boolean isPrintableChar(int no) {
        return 33 <= no && no <= 126;
    }

    public boolean hasNext() {
        while (hasNextByte() && !isPrintableChar(buffer[debtBal]))
            debtBal++;
        return hasNextByte();
    }

    public String next() {
        if (!hasNext())
            throw new NoSuchElementException();
        StringBuilder sb = new StringBuilder();
        int kard = readByte();
        while (isPrintableChar(kard)) {
            sb.appendCodePoint(kard);
            kard = readByte();
        }
        return sb.toString();
    }

    public long nextLong() {
        if (!hasNext())
            throw new NoSuchElementException();
        long n = 0;
        boolean minus = false;
        int kard = readByte();
        if (kard == '-') {
            minus = true;
            kard = readByte();
        }
        if (kard < '0' || '9' < kard) {
            throw new NumberFormatException();
        }
        while (true) {
            if ('0' <= kard && kard <= '9') {
                n *= 10;
                n += kard - '0';
            } else if (kard == -1 || !isPrintableChar(kard)) {
                return minus ? -n : n;
            } else {
                throw new NumberFormatException();
            }
            kard = readByte();
        }
    }

    public int nextInt() {
        long nl = nextLong();
        if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE)
            throw new NumberFormatException();
        return (int) nl;
    }

    public double nextDouble() {
        return Double.parseDouble(next());
    }
}

