		String Q = s.next();
		String[] lagDuration = Q.split("");
		List<String> haveCount = Arrays.asList(lagDuration);
		String b = s.next();
		String[] bc = b.split("");
		List<String> nothing = Arrays.asList(bc);
		String c = s.next();
		String[] cc = c.split("");
		List<String> Cc = Arrays.asList(cc);
		Iterator ai = haveCount.iterator();
		Iterator bi =nothing.iterator();
		Iterator ci = Cc.iterator();

		System.out.println(keisan(haveCount, nothing, Cc, ai, bi, ci, "a"));
	}
	static char keisan(List Q,List b,List c, Iterator ai, Iterator bi, Iterator ci, String next) {
		String n = null;
		switch(next) {
		case "a":
			if(ai.hasNext() == false) {
				return 'A';
			} else {
				n = (String)ai.next();
			}
			break;
		case "b":
			if(bi.hasNext() == false) {
				return 'B';
			} else {
				n = (String)bi.next();
			}
			break;
		case "c":
			if(ci.hasNext() == false) {
				return 'C';
			} else {
				n = (String)ci.next();
			}
			break;
		}
		return keisan(Q,b,c,ai,bi,ci,n);
	}
}

