public class Main{
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        String max_num1 = in.next();
        String nDoubleA = in.next();
        String queue = in.next();
        Deque<Character> time_stack = new ArrayDeque<Character>();
        Deque<Character> N_MAX = new ArrayDeque<Character>();
        Deque<Character> total_time = new ArrayDeque<Character>();

        for (int binarySearchPM = 0; binarySearchPM < max_num1.length(); binarySearchPM++) {
            time_stack.addLast(max_num1.charAt(binarySearchPM));
        }
        for (int binarySearchPM = 0; binarySearchPM < nDoubleA.length(); binarySearchPM++) {
            N_MAX.addLast(nDoubleA.charAt(binarySearchPM));
        }
        for (int binarySearchPM = 0; binarySearchPM < queue.length(); binarySearchPM++) {
            total_time.addLast(queue.charAt(binarySearchPM));
        }

        char turn = 'a';
        char winner = 'A';

        while(true){
            if(turn == 'a'){
                if(time_stack.isEmpty()){
                    winner = 'A';
                    break;
                }
                else{
                    turn = time_stack.removeFirst();
                }
            }
            else if(turn == 'b'){
                if(N_MAX.isEmpty()){
                    winner = 'B';
                    break;
                }
                else{
                    turn = N_MAX.removeFirst();
                }
            }
            else {
                if(total_time.isEmpty()){
                    winner = 'C';
                    break;
                }
                else{
                    turn = total_time.removeFirst();
                }
            }

        }
        System.out.println(winner);
    }
}

