import java.util.*;

public class Main {

  public static void main (String[] args) {

    Scanner aargs = new Scanner(System.in);

    String timeCount = aargs.next();

    aargs.close();

    String[] gcdOfFactorial = timeCount.split("");

    Deque<String> calculateLeastCommonMultiplyer = new ArrayDeque<>();

    for (int Binomial = 0; Binomial < gcdOfFactorial.length; Binomial++) {
      if (gcdOfFactorial[Binomial].equals("0")) {
        calculateLeastCommonMultiplyer.addLast("0");
      }
      if (gcdOfFactorial[Binomial].equals("1")) {
        calculateLeastCommonMultiplyer.addLast("1");
      }
      if (gcdOfFactorial[Binomial].equals("B")) {
        if (0 < calculateLeastCommonMultiplyer.size()) {
          calculateLeastCommonMultiplyer.pollLast();
        }
      }
    }

    int intb = calculateLeastCommonMultiplyer.size();

    for (int Binomial = 0; Binomial < intb; Binomial++) {
      System.out.print(calculateLeastCommonMultiplyer.pollFirst());
    }

    System.out.println("");

  }

}

